require(['jquery'], function($) {
  // Create the categories under the new blog, unless their parent is changed.
  $(function() {
    var blogParent = $('#blogLocationParentReference');
    var blogName = $('#blogLocationName');
    var categoriesParent = $('#blogCategoriesLocationParentReference');
    var categoriesParentChanged = false;
    categoriesParent.on('input xwiki:suggest:selected', function() {
      categoriesParentChanged = true;
    });
    blogParent.add(blogName).on('input change xwiki:suggest:selected', function() {
      if (!categoriesParentChanged) {
        categoriesParent.val([blogParent.val(), blogName.val()].filter(Boolean).join('.')).trigger('change');
      }
    });
  });
});
